#include <stdio.h>
#include <limits.h>

void check_integer_overflow(const char* index_str) {
    long index = strtol(index_str, NULL, 10);
    if (index == LONG_MAX || index == LONG_MIN) {
        printf("Integer overflow detected for input: %s\n", index_str);
    } else {
        printf("Valid index: %ld\n", index);
    }
}

int main() {
    check_integer_overflow("2147483648"); // Example of a large number
    check_integer_overflow("100");        // Example of a valid number
